+//version 8:
+import lombok.Builder;
+import lombok.Value;
+import lombok.experimental.SuperBuilder;
+
+public class BuilderDefaultsGenericsInference {
+	@Value
+	static class MyClass<T> {
+		T value;
+
+		static MyClass<Integer> myInt() {
+			return new MyClass<>(42);
+		}
+
+		static MyClass<Character> myChar() {
+			return new MyClass<>('A');
+		}
+	}
+
+	static String doSth(MyClass<Integer> i, MyClass<Character> c) {
+		return i.value.toString() + c.value.toString();
+	}
+
+	@Builder
+	static class BuilderDefaults {
+		@Builder.Default
+		String foo = doSth(MyClass.myInt(), MyClass.myChar());
+	}
+
+	@SuperBuilder
+	static class SuperBuilderDefaults {
+		@Builder.Default
+		String foo = doSth(MyClass.myInt(), MyClass.myChar());
+	}
+
+	public static void main(String... args) {
+		String value = BuilderDefaults.builder().build().foo;
+		if (!"42A".equals(value)) throw new AssertionError(value);
+		value = BuilderDefaults.builder().foo("override").build().foo;
+		if (!"override".equals(value)) throw new AssertionError(value);
+		value = SuperBuilderDefaults.builder().build().foo;
+		if (!"42A".equals(value)) throw new AssertionError(value);
+		value = SuperBuilderDefaults.builder().foo("override").build().foo;
+		if (!"override".equals(value)) throw new AssertionError(value);
+	}
+}
